import {Component, HostBinding, OnInit} from '@angular/core';
import {ActivatedRoute, NavigationExtras, Router} from '@angular/router';

import {NavController, Platform} from '@ionic/angular';
import {routeAnimation} from '../../shared';
import {Plugins} from '@capacitor/core';
import 'ocr';
import {HttpClientService} from '../../shared/http-client.service';
import {isNotNullOrUndefined} from 'codelyzer/util/isNotNullOrUndefined';
import {ModalService} from 'ng-zorro-antd-mobile';
import {environment} from "../../../environments/environment";

const { Ocr } = Plugins;
@Component({
    selector: 'app-bottle-list',
    templateUrl: 'bottle-list.page.html',
    styleUrls: ['bottle-list.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class BottleListPage implements OnInit {
    titleInfo = '';
    contentInfo = '';
    bottleList = [];
    isCloseBox = '0'; // 0 开箱 1 封箱
    removeScannerHandler;
    result: { name: string, sex: string, folk: string, birthday: string, num: string, address: string, imageData: string };
    tubeUuid;
    tubeBarcode;
    right = [
        {
            text: '删除',
            onPress: () => {
                this.showDelete();
            },
            className: 'btnClass'
        }
    ];
    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private platform: Platform,
        private route: ActivatedRoute,
        private deleteModal: ModalService
    ) {
        // 控制app返回按钮
        this.platform.backButton.subscribeWithPriority(10, () => {
            this.routeBack();
        });
    }

    @HostBinding('@routeAnimation') state;   // 路由动画
    ngOnInit() {
    }

    ionViewWillEnter() {
        this.titleInfo = sessionStorage.getItem('boxBarcode');
        this.isCloseBox = sessionStorage.getItem('isCloseBox');
        // 获取管列表
        this.ListBoxTube(sessionStorage.getItem('boxBarId'));
    }

    // 路由返回
    routeBack() {
        this.router.navigate(['/BoxList']);
       //   this.router.navigate(['/tabs/tab1']);
    }

    onClick(value, i) {
        sessionStorage.setItem('tubeBarcode', value.tubeBarcode);
        sessionStorage.setItem('tubeBarId', value.tubeBarId);
        if (!isNotNullOrUndefined(value.closedTube) || !value.closedTube){
            if (this.isCloseBox === '1') {
                sessionStorage.setItem('isClosedTube', '1');
            } else {
                sessionStorage.setItem('isClosedTube', '0');
            }
        } else {
            sessionStorage.setItem('isClosedTube', '1');
        }
        this.router.navigate(['/PersonList']);
    }

    // 打开删除按钮时，获取当前管子的UUID
    openDelete(uuid, tubeBarcode){
        this.tubeUuid = uuid;
        this.tubeBarcode = tubeBarcode;
    }
    // 删除采集管
    showDelete() {
        this.deleteModal.alert('', '确认删除?', [
            { text: '取消', onPress: () => {} },
            { text: '删除', onPress: () => {
                    this.deleteTube();
                }}
        ]);
    }
    clickScan() {
        this.router.navigate(['/BottleBarcode']);
    }

    // 调用后台接口
    // 根据箱查询所有管
    ListBoxTube(uuid){
        this.bottleList = [];
        const condition = {
            boxBarId:  uuid,
        };
        this.http
            .get(`rcp/api/tube/operate/listBoxTube`, condition , '根据箱查询所有管', environment.FailMessage.getBoxTube)
            .subscribe( data => {
                if (data['isSuccess']){
                 this.bottleList = data['data'];
               }
            });
    }
    // 封箱
    confirmBox(){
        const condition = {
            boxBarcode: sessionStorage.getItem('boxBarcode'),
            boxState: 'CloseBox'
        };
        this.http
            .get(`rcp/api/box/operate/scan`, condition , '扫描转运箱条码', environment.FailMessage.confirmBox)
            .subscribe( data => {
                if (data['isSuccess']){
                    const successNavigationExtras: NavigationExtras = {
                        queryParams: {
                            ContentId: '1',
                            Barcode: sessionStorage.getItem('boxBarcode')
                        }
                    };
                    this.router.navigate(['/Success'], successNavigationExtras);
                }
            });
    }
    // 封管操作
    confirmTube(tubebarcode, tubebarcodeId, $event){
        $event.stopPropagation();
        const condition = {
            boxBarId:  sessionStorage.getItem('boxBarId'),
            tubeBarId: tubebarcodeId,
            tubeBarcode: tubebarcode,
            tubeState: 'CloseBar'
        };
        this.http
            .get(`rcp/api/tube/operate/confirmTube`, condition , '确认采集管', 'false')
            .subscribe( data => {
                if (data['code'] === '0'){
                    if (isNotNullOrUndefined(data['message'])) {
                        this.http.showToast(data['message']);
                        // 封管时已封箱-扫码新箱
                        // const navigationExtras: NavigationExtras = {
                        //     queryParams: { boxBarcode: sessionStorage.getItem('boxBarcode')}
                        // };
                        // this.router.navigate(['/tabs/tab1'], navigationExtras);
                    } else {
                        this.http.showToast('封管成功');
                        // 封管后刷新界面
                        this.ionViewWillEnter();
                    }
                }
            });
    }
    deleteTube(){
        const condition = {
            boxBarId:  sessionStorage.getItem('boxBarId'),
            tubeBarId: this.tubeUuid,
            tubeBarcode: this.tubeBarcode
        };
        this.http
            .get(`rcp/api/tube/operate/deleteTube` , condition,
                '删除采集管', environment.FailMessage.deleteSample)
            .subscribe( data => {
                // 删除成功后，重新获取当前管子里的标本列表
                if (data['isSuccess']){
                    this.http.showToast('删管成功');
                    this.ListBoxTube(sessionStorage.getItem('boxBarId'));
                }
            });
    }
}
